/bin/zsh -lc "node <<'NODE'
const fs = require('node:fs');
const cp = require('node:child_process');
const fixedPoint = cp.execFileSync('git', ['rev-parse', 'HEAD'], {encoding:'utf8'}).trim();
const reason = 'Isolated subagent spawning is unavailable in this evaluation runtime; neither reviewer could be started.';
const reviewer = (spec) => ({status:'not_started', agent_id:null, context_id:null, spec, model:'gpt-5.6-sol', reasoning_effort:'medium', findings:null, verdict:null, summary:reason});
const record = {
  workspace_root:process.cwd(),
  fixed_point:{ref:'HEAD', commit:fixedPoint},
  diff_source:'change.diff',
  status:'blocked',
  review_verdict_available:false,
  reviewers:{standards:reviewer('docs/specs/496/product-spec.md'), spec:reviewer('docs/specs/496/architecture-spec.md')},
  unresolved_blockers:[reason],
  inline_review_performed:false
};
fs.mkdirSync('.eval-output/review', {recursive:true});
const path = '.eval-output/review/contexts.json';
fs.writeFileSync(path, JSON.stringify(record, null, 2) + '\\n');
if ("'!fs.existsSync(path)) throw new Error('"'Output missing');
const parsed = JSON.parse(fs.readFileSync(path, 'utf8'));
if (parsed.review_verdict_available "'!== false || Object.values(parsed.reviewers).some(r => r.status !== '"'not_started' || r.agent_id "'!== null || r.context_id !== null || r.verdict !== null)) throw new Error('"'Invalid unavailable-review record');
console.log('Verified: ' + path + ' exists, parses, and records both reviewers as not started with no verdict or invented IDs.');
NODE"

